window.addEventListener('keydown',e=>{if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code)&&!$('map-dialog').open)e.preventDefault();if(e.repeat)return;if(e.code==='KeyM'){e.preventDefault();openMap();return}if($('map-dialog').open)return;if(e.code==='Enter'&&state==='menu'){e.preventDefault();start();return}if(e.code==='KeyP'||e.code==='Escape'){e.preventDefault();pause();return}if(e.code==='KeyF'){land();return}if(e.code==='KeyR'){alignCourse();return}if(state==='flight')keys.add(e.code)});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{clearInput();if(state==='flight'&&!$('map-dialog').open)pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='flight'&&!$('map-dialog').open)pause()});
function moveStick(e){const r=$('joystick').getBoundingClientRect();stick.x=clamp((e.clientX-r.left-r.width/2)/32,-1,1);stick.y=clamp(-(e.clientY-r.top-r.height/2)/32,-1,1);$('stick').style.transform=`translate(${stick.x*27}px,${-stick.y*27}px)`}
$('joystick').addEventListener('pointerdown',e=>{$('joystick').setPointerCapture(e.pointerId);moveStick(e)});$('joystick').addEventListener('pointermove',e=>{if($('joystick').hasPointerCapture(e.pointerId))moveStick(e)});for(const ev of ['pointerup','pointercancel','lostpointercapture'])$('joystick').addEventListener(ev,()=>{stick.x=stick.y=0;$('stick').style.transform=''});
for(const [id,set] of [['touch-boost',v=>boostHeld=v],['touch-brake',v=>brakeHeld=v]]){$(id).addEventListener('pointerdown',e=>{$(id).setPointerCapture(e.pointerId);set(true)});for(const ev of ['pointerup','pointercancel','lostpointercapture'])$(id).addEventListener(ev,()=>set(false))}
